#ifndef RPNCE_CORE_UNITS_H
#define RPNCE_CORE_UNITS_H

/* Unit conversions. A stack value can carry a unit; pressing another unit
 * of the same dimension converts it. The tables are generated by
 * tools/genunits.py from exact definitions. */

#include <stdbool.h>
#include <stdint.h>
#include <ti/real.h>
#include "units_count.h"

/* The unit table, read through these (from the RPNCEres appvar on the
 * calculator; from a generated C copy in the PC tests). */
const char *unit_label(uint8_t u);      /* as in the menu, with symbol codes */
uint8_t unit_dim(uint8_t u);            /* DIM_* */
const char *unit_factor(uint8_t u);     /* one unit in the dimension's base unit */
const char *unit_offset(uint8_t u);     /* temperatures: base = (value + offset)
                                         * x factor; NULL for none */
bool unit_reciprocal(uint8_t u);        /* fuel: base = factor / value (mpg) */
uint8_t unit_base_of(uint8_t dim);      /* the dimension's base unit */

/* Converts a value between units of the same dimension. Call under the
 * error handler (dividing by a zero mpg, for example, raises an error). */
real_t unit_convert(const real_t *value, uint8_t from, uint8_t to);

#endif
